}

public class Main {
    public static void main(String[] args) {
        // Upcasting (Automatic)
        Animal a = new Dog(); 

        // Downcasting (Explicit & requires checking)
        if (a instanceof Dog) {
            Dog d = (Dog) a;
            d.bark(); // Safe to call child-specific method
        }
    }
}

